endpoint.request:
{ action: "complete", task_ids: int[1..200], closure_feedback?: string|null,
  validation_status_id?: int|null, time_entry?: { date, task_type_id, minutes, start_time?, end_time?, notes? },
  time_entry_shares?: [{ task_id, minutes }] }

endpoint.errors:
403 senza tasks.complete (invariato);
422 validazione `time_entry_shares` / `time_entry.*` (nessuna scrittura);
422 { success: false, message, errors: { task_ids: [..] }, incompatible_tasks: [{ id, reason }] } (invariato).

endpoint.request:
{ action: "complete", task_ids: int[1..200], closure_feedback?: string|null, for_all_assignees?: bool,
  time_entry: { date, task_type_id, minutes, start_time?, end_time?, notes? },
  time_entry_shares: [{ task_id, minutes }] }

endpoint.errors:
409 commessa chiusa (invariato); 422 task non radice di questa commessa (invariato);
422 validazione `time_entry_shares` / `time_entry.*`;
422 NUOVO per action=complete: { success: false, message, errors: { task_ids: [..] },
  incompatible_tasks: [{ id, reason }] } — nessun task chiuso, nessun segnatempo, nessuna notifica.
Le altre action restano 200 best-effort con `results`.
